<template><div class="app-container"><el-alert title="案例研究只展示真实采集的来源、数据和人工采用/淘汰决定。它不等于可直接套用：每条采用项都必须同时查看不可复制边界。" type="info" :closable="false" class="mb16"/><el-form ref="queryRef" :model="query" :inline="true"><el-form-item label="租户"><el-input v-model="query.tenantId" style="width:180px"/></el-form-item><el-form-item label="受众"><el-select v-model="query.audienceType" clearable style="width:180px"><el-option label="B2B美业老板" value="B2B_BEAUTY_OWNER"/><el-option label="B2C门店消费者" value="B2C_STORE_CONSUMER"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="search">搜索</el-button></el-form-item></el-form><el-table v-loading="loading" :data="rows"><el-table-column label="研究名称" prop="researchName" min-width="280"/><el-table-column label="受众" prop="audienceType" width="170"/><el-table-column label="研究问题" prop="problemSnapshot" min-width="320" show-overflow-tooltip/><el-table-column label="状态" prop="lifecycleStatus" width="150"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" icon="View" @click="show(s.row)">解释链</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/><el-drawer v-model="open" title="案例研究解释链" size="78%"><el-descriptions :column="1" border><el-descriptions-item label="问题">{{ detail.problemSnapshot }}</el-descriptions-item><el-descriptions-item label="假设">{{ detail.hypothesisSnapshot }}</el-descriptions-item><el-descriptions-item label="共享结构">{{ detail.sharedStructureSnapshot }}</el-descriptions-item><el-descriptions-item label="不变项">{{ detail.invariantSnapshot }}</el-descriptions-item><el-descriptions-item label="唯一变化轴">{{ detail.variantAxis }}</el-descriptions-item></el-descriptions><el-table :data="detail.items" class="mt16"><el-table-column label="#" prop="ordinalNo" width="55"/><el-table-column label="来源" min-width="210"><template #default="s"><a v-if="s.row.sourceUrl" :href="s.row.sourceUrl" target="_blank" rel="noopener">{{ s.row.sourceCode }} · {{ s.row.titleSnapshot }}</a><span v-else>{{ s.row.sourceCode }} · {{ s.row.titleSnapshot }}</span></template></el-table-column><el-table-column label="数据快照" prop="performanceSnapshot" min-width="150"/><el-table-column label="决定" width="110"><template #default="s"><el-tag :type="s.row.decisionStatus==='ADOPTED'?'success':'info'">{{ s.row.decisionStatus }}</el-tag></template></el-table-column><el-table-column label="采用角色" prop="sourceRole" width="150"/><el-table-column label="决定理由" prop="decisionReason" min-width="230"/><el-table-column label="可学内容" prop="learnableSnapshot" min-width="230"/><el-table-column label="不可复制边界" prop="nonReusableSnapshot" min-width="230"/></el-table></el-drawer></div></template>
<script setup lang="ts">import { reactive,ref } from 'vue';import { getTopicCaseResearch,listTopicCaseResearch } from '@/api/topic/caseResearch';import type { TopicCaseResearch,TopicCaseResearchQueryParams } from '@/types';const rows=ref<TopicCaseResearch[]>([]),detail=ref<TopicCaseResearch>({}),loading=ref(false),open=ref(false),total=ref(0);const query=reactive({pageNum:1,pageSize:10,tenantId:'local-preview'} as TopicCaseResearchQueryParams);function load(){loading.value=true;listTopicCaseResearch(query).then(r=>{rows.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)}function search(){query.pageNum=1;load()}function show(r:TopicCaseResearch){getTopicCaseResearch(r.id as string).then(v=>{detail.value=v.data||{};open.value=true})}load()</script><style scoped>.mb16{margin-bottom:16px}.mt16{margin-top:16px}</style>
